files.app/globals.css:
:root {
  color-scheme: light;
  --bg: #f2f3f7;
  --ink: #1a1e2b;
  --muted: #5f6b7f;
  --line: #d8dce6;
  --line-light: #e9ecf2;
  --panel: #ffffff;
  --red: #d9363e;
  --green: #0e9d5d;
  --blue: #2b6de5;
  --gold: #b88719;
  --purple: #7c3aed;
  --teal: #0f8f88;
  --amber-bg: #fff8e5;
  --red-bg: #fef2f2;
  --green-bg: #f0fdf4;
  --blue-bg: #eef4ff;
  --surface-1: #f7f8fb;
  --surface-2: #fafbfd;
  --shadow-sm: 0 1px 2px rgba(15,23,42,0.04);
  --shadow-md: 0 4px 12px rgba(15,23,42,0.06);
  --red-fill: #fef0ef;
  --green-fill: #edf9f2;
  --volume-up-fill: #f2c4c0;
  --volume-down-fill: #b0e0c6;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family:
    -apple-system, BlinkMacSystemFont, "Segoe UI",
    "PingFang SC", "Microsoft YaHei",
    "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-variant-numeric: tabular-nums;
}

button,
input,
select,
textarea {
  font: inherit;
}

/* ==================== SHELL ==================== */

.dashboard-shell {
  width: min(1360px, calc(100vw - 40px));
  margin: 0 auto;
  padding: 24px 0 56px;
}

.hero-panel {
  margin-bottom: 16px;
  padding: 20px;
  border: 1px solid rgba(43, 109, 229, 0.16);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(247, 250, 255, 0.98)),
    var(--panel);
  box-shadow: var(--shadow-md);
}

.eyebrow {
  display: inline-flex;
  width: fit-content;
  margin: 0 0 4px;
  padding: 4px 9px;
  border: 1px solid rgba(43, 109, 229, 0.18);
  border-radius: 999px;
  color: var(--blue);
  background: rgba(43, 109, 229, 0.08);
  font-size: 13px;
  font-weight: 700;
}

/* ==================== TOP BAR ==================== */

.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0;
  margin-bottom: 12px;
  font-size: 13px;
  color: var(--muted);
}

.top-bar .freshness {
  display: flex;
  align-items: center;
  gap: 6px;
}

.top-bar .freshness::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
}

/* ==================== PRICE HEADER ==================== */

.price-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 4px;
}

.price-header .id-area {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.price-header .id-area .name {
  font-size: clamp(34px, 4vw, 52px);
  font-weight: 900;
  line-height: 1;
  word-break: break-word;
}

.price-header .id-area .symbol {
  font-size: 15px;
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.price-header .quote-area {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px 10px;
  flex-shrink: 0;
  text-align: right;
  max-width: 520px;
}

.price-header .quote-area .price {
  font-size: clamp(36px, 4.2vw, 58px);
  font-weight: 900;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  letter-spacing: 0;
  line-height: 1;
  white-space: nowrap;
}

.price-header .quote-area .price.is-missing {
  font-size: clamp(22px, 2.2vw, 30px);
  color: var(--muted);
  font-family: inherit;
}

.price-header .quote-area .change {
  font-size: 16px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  color: #fff;
}

.price-header .quote-area .change.up {
  background: var(--red);
}

.price-header .quote-area .change.down {
  background: var(--green);
}

.price-header .quote-area .change.neutral {
  color: var(--muted);
  background: var(--surface-1);
  border: 1px solid var(--line);
}

.quote-note {
  width: 100%;
  color: var(--muted);
  font-size: 13px;
}

/* ==================== META ROW ==================== */

.meta-row {
  display: grid;
  grid-template-columns: repeat(6, minmax(110px, 1fr)) auto;
  align-items: stretch;
  gap: 10px;
  margin: 16px 0 0;
}

.meta-row .meta-item {
  display: grid;
  gap: 7px;
  min-height: 70px;
  padding: 12px;
  border: 1px solid rgba(216, 220, 230, 0.9);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.74);
  font-size: 14px;
}

.meta-row .meta-item .meta-label {
  color: var(--muted);
}

.meta-row .meta-item .meta-value {
  font-weight: 600;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 18px;
  overflow-wrap: anywhere;
}

.insight-strip {
  display: grid;
  grid-template-columns: 1.15fr 0.9fr 1.35fr;
  gap: 12px;
  margin-top: 14px;
}

.insight-strip article {
  min-height: 88px;
  padding: 14px;
  border: 1px solid rgba(43, 109, 229, 0.12);
  border-radius: 8px;
  background: #f8fbff;
}

.insight-strip span {
  display: block;
  margin-bottom: 8px;
  color: var(--blue);
  font-size: 13px;
  font-weight: 800;
}

.insight-strip strong {
  display: block;
  color: #1f2937;
  font-size: 15px;
  line-height: 1.65;
}

/* ==================== METRIC STRIP ==================== */

.metric-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(140px, 100%), 1fr));
  gap: 1px;
  margin-bottom: 24px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.metric-strip .metric-cell {
  display: flex;
  min-width: 0;
  min-height: 82px;
  flex-direction: column;
  justify-content: center;
  padding: 12px 14px;
  background: var(--panel);
}

.metric-strip .metric-cell .metric-label {
  display: block;
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 500;
}

.metric-strip .metric-cell .metric-value {
  min-width: 0;
  font-size: clamp(16px, 1.35vw, 20px);
  font-weight: 700;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-variant-numeric: tabular-nums lining-nums;
  line-height: 1.25;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.metric-strip.metrics-7 {
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.metric-strip.metrics-4,
.metric-strip.four-col {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

/* ==================== SECTION DIVIDER ==================== */

.section-divider {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 28px 0 14px;
}

.section-divider:first-of-type {
  margin-top: 0;
}

.section-divider h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  flex-shrink: 0;
}

.section-divider .section-meta {
  font-size: 13px;
  color: var(--muted);
}

.section-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--line);
}

/* ==================== CHART ZONE ==================== */

.chart-zone {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.75fr);
  gap: 16px;
  margin-bottom: 24px;
}

.chart-zone > *,
.content-grid > *,
.content-grid.wide > *,
.backtest-grid > *,
.main-grid > *,
.detail-grid > * {
  min-width: 0;
}

.chart-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  padding: 16px;
  box-shadow: var(--shadow-sm);
}

.data-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  min-width: 0;
  overflow: hidden;
}

/* ==================== TREND CHART ==================== */

.trend-chart {
  width: 100%;
  height: 380px;
  overflow: hidden;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.volume-chart {
  width: 100%;
  height: 100px;
  margin-top: 10px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.chart-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 8px;
  font-size: 13px;
  color: var(--muted);
}

.chart-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.chart-legend span::before {
  content: "";
  width: 16px;
  height: 3px;
  border-radius: 999px;
  background: currentColor;
}

.chart-empty-state {
  display: grid;
  gap: 6px;
  margin-bottom: 10px;
  padding: 12px 14px;
  border: 1px dashed rgba(43, 109, 229, 0.28);
  border-radius: 6px;
  color: var(--muted);
  background: #f8fbff;
}

.chart-empty-state strong {
  color: var(--ink);
  font-size: 15px;
}

.chart-empty-state span {
  font-size: 13px;
  line-height: 1.6;
}

.legend-price { color: var(--ink); }
.legend-ma5 { color: var(--blue); }
.legend-ma10 { color: var(--gold); }
.legend-ma20 { color: var(--purple); }
.legend-ma60 { color: var(--teal); }

.chart-bg { fill: var(--surface-1); }

.chart-label {
  fill: var(--muted);
  font-size: 12px;
  paint-order: stroke;
  stroke: var(--surface-1);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}

.chart-price {
  text-anchor: end;
  dominant-baseline: central;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}

.chart-date { text-anchor: middle; }

.axis {
  stroke: var(--line);
  stroke-width: 1.2;
}

.axis.muted { opacity: 0.5; }

.axis.grid {
  opacity: 0.4;
  stroke-dasharray: 2 3;
}

.equity-line {
  fill: none;
  stroke: var(--gold);
  stroke-width: 2.4;
  vector-effect: non-scaling-stroke;
}

.candle-up line,
.candle-up rect {
  fill: var(--red-fill);
  stroke: var(--red);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}

.candle-down line,
.candle-down rect {
  fill: var(--green-fill);
  stroke: var(--green);
  stroke-width: 1.2;
  vector-effect: non-scaling-stroke;
}

.ma-line {
  fill: none;
  stroke-width: 1.5;
  vector-effect: non-scaling-stroke;
}

.ma5 { stroke: var(--blue); }
.ma10 { stroke: var(--gold); }
.ma20 { stroke: var(--purple); }
.ma60 { stroke: var(--teal); stroke-width: 1.8; }

.volume-up {
  fill: var(--volume-up-fill);
  stroke: var(--red);
  stroke-width: 0.5;
  vector-effect: non-scaling-stroke;
}

.volume-down {
  fill: var(--volume-down-fill);
  stroke: var(--green);
  stroke-width: 0.5;
  vector-effect: non-scaling-stroke;
}

/* ==================== PANEL HEADING ==================== */

.panel-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.panel-heading.compact {
  align-items: flex-start;
}

.panel-heading h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 700;
}

.panel-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.panel-heading .pill {
  flex-shrink: 0;
  padding: 3px 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

/* ==================== SIGNAL LIST ==================== */

.signal-list {
  display: grid;
  gap: 8px;
}

.signal-list .signal-item {
  padding: 12px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.signal-list .signal-item.signal-up {
  border-color: color-mix(in srgb, var(--red) 28%, var(--line));
  background: var(--red-bg);
}

.signal-list .signal-item.signal-down {
  border-color: color-mix(in srgb, var(--green) 28%, var(--line));
  background: var(--green-bg);
}

.signal-list .signal-item.signal-risk {
  border-color: color-mix(in srgb, var(--gold) 34%, var(--line));
  background: var(--amber-bg);
}

.signal-list .signal-item.signal-risk.risk-高 {
  border-color: color-mix(in srgb, var(--red) 36%, var(--line));
  background: var(--red-bg);
}

.signal-list .signal-item .signal-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 13px;
}

.signal-list .signal-item .signal-value {
  font-size: 18px;
  font-weight: 700;
  white-space: nowrap;
}

.signal-list .signal-item .signal-detail {
  display: block;
  margin-top: 2px;
  font-weight: 400;
  font-size: 13px;
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

/* ==================== TECHNICAL CONDITIONS ==================== */

.technical-condition-panel {
  border-top: 0;
}

.technical-condition-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border: 1px solid var(--line-light);
}

.technical-condition-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 5px 12px;
  min-width: 0;
  padding: 12px 14px;
  border-right: 1px solid var(--line-light);
}

.technical-condition-row:last-child {
  border-right: 0;
}

.technical-condition-row > span,
.technical-condition-row > small {
  color: var(--muted);
}

.technical-condition-row > span {
  font-size: 13px;
  font-weight: 700;
}

.technical-condition-row > strong {
  font-size: 14px;
}

.technical-condition-row > small {
  grid-column: 1 / -1;
  overflow: hidden;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.condition-positive { color: var(--green); }
.condition-negative { color: var(--red); }
.condition-neutral { color: var(--gold); }

.technical-boundary-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border: 1px solid var(--line-light);
  border-top: 0;
}

.technical-boundary-strip > span {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 10px 14px;
  border-right: 1px solid var(--line-light);
  color: var(--muted);
  font-size: 12px;
}

.technical-boundary-strip > span:last-child {
  border-right: 0;
}

.technical-boundary-strip strong {
  overflow: hidden;
  color: var(--ink);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 800px) {
  .technical-condition-grid,
  .technical-boundary-strip {
    grid-template-columns: 1fr;
  }

  .technical-condition-row,
  .technical-boundary-strip > span {
    border-right: 0;
    border-bottom: 1px solid var(--line-light);
  }

  .technical-condition-row:last-child,
  .technical-boundary-strip > span:last-child {
    border-bottom: 0;
  }
}

/* ==================== WARNING LIST ==================== */

.warning-list {
  display: grid;
  gap: 6px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.warning-list li {
  padding: 8px 10px;
  border: 1px solid color-mix(in srgb, var(--gold) 38%, white);
  border-radius: 6px;
  color: #805600;
  background: var(--amber-bg);
  font-size: 13px;
}

/* ==================== QUALITY PILL ==================== */

.quality-pill {
  font-weight: 700;
}

.quality-ok {
  border-color: color-mix(in srgb, var(--green) 28%, var(--line)) !important;
  color: var(--green) !important;
  background: var(--green-bg);
}

.quality-warning {
  border-color: color-mix(in srgb, var(--gold) 34%, var(--line)) !important;
  color: #805600 !important;
  background: var(--amber-bg);
}

.quality-error {
  border-color: color-mix(in srgb, var(--red) 32%, var(--line)) !important;
  color: var(--red) !important;
  background: var(--red-bg);
}

.quality-muted {
  color: var(--muted) !important;
  background: #f8fafc;
}

/* ==================== BACKTEST ==================== */

.backtest-section {
  margin-bottom: 24px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow-sm);
}

.backtest-section .metric-strip {
  margin-bottom: 14px;
}

.backtest-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: 14px;
  margin-top: 14px;
}

.chart-panel.embedded {
  margin-top: 0;
}

/* ==================== CONTENT GRID ==================== */

.content-grid {
  display: grid;
  grid-template-columns: minmax(260px, 0.9fr) minmax(0, 1.4fr);
  gap: 16px;
  margin-bottom: 16px;
}

.content-grid.wide {
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.8fr);
}

.content-grid.single-column {
  grid-template-columns: minmax(0, 1fr);
}

/* ==================== FUNDAMENTAL SNAPSHOT ==================== */

.financial-snapshot-grid {
  display: grid;
  grid-template-columns: minmax(280px, 0.75fr) minmax(0, 1.65fr);
  gap: 16px;
  margin-bottom: 16px;
}

.financial-snapshot-grid > * {
  min-width: 0;
}

.financial-quality-panel {
  border-color: color-mix(in srgb, var(--blue) 25%, var(--line));
  background: linear-gradient(145deg, var(--panel), var(--blue-bg));
}

.quality-score-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 16px;
  margin: 16px 0;
}

.quality-score-row > strong {
  color: var(--blue);
  font-size: clamp(38px, 5vw, 58px);
  line-height: 1;
}

.quality-score-row > div > span {
  font-weight: 700;
}

.quality-score-track {
  height: 8px;
  margin-top: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--line-light);
}

.quality-score-track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--teal), var(--blue));
}

.quality-facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.quality-facts > div,
.quality-limitations {
  padding: 10px 12px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: color-mix(in srgb, var(--panel) 90%, transparent);
}

.quality-facts h3,
.quality-limitations strong {
  margin: 0 0 6px;
  font-size: 13px;
}

.quality-facts ul {
  margin: 0;
  padding-left: 18px;
}

.quality-facts li,
.quality-facts p,
.quality-limitations p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.55;
}

.quality-limitations {
  margin-top: 10px;
}

/* ==================== MINI METRICS ==================== */

.mini-metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin: 12px 0 16px;
}

.mini-metric-grid .mini-metric {
  padding: 10px 12px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.mini-metric-grid .mini-metric span {
  display: block;
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 13px;
}

.mini-metric-grid .mini-metric strong {
  font-size: 18px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  white-space: nowrap;
}

/* ==================== FINANCIAL BARS ==================== */

.financial-bars {
  display: grid;
  grid-template-columns: repeat(6, minmax(34px, 1fr));
  gap: 8px;
  align-items: end;
  height: 180px;
  margin: 8px 0 16px;
  padding: 12px 8px 0;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.financial-bar-group {
  display: grid;
  gap: 6px;
  align-items: end;
  min-width: 0;
  height: 100%;
}

.bar-stack {
  position: relative;
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 3px;
  height: 130px;
}

.bar {
  width: 10px;
  min-height: 4px;
  border-radius: 999px 999px 2px 2px;
}

.bar.revenue { background: var(--blue); }
.bar.profit { background: var(--gold); }

.financial-bar-group small {
  overflow: hidden;
  color: var(--muted);
  font-size: 12px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ==================== ANNOUNCEMENTS ==================== */

.announcement-list {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.announcement-list li {
  padding: 10px 12px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.announcement-list span,
.announcement-list em {
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
}

.announcement-list strong {
  display: block;
  margin: 4px 0;
  font-size: 15px;
  line-height: 1.45;
}

/* ==================== CORRELATION ==================== */

.correlation-list {
  display: grid;
  gap: 10px;
}

.correlation-row {
  display: grid;
  grid-template-columns: minmax(140px, 0.9fr) minmax(100px, 1fr) 56px;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border: 1px solid var(--line-light);
  border-radius: 6px;
  background: var(--surface-1);
}

.correlation-row strong {
  display: block;
  font-size: 14px;
}

.correlation-row small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.correlation-row .corr-value {
  color: var(--ink);
  font-weight: 700;
  font-size: 15px;
  text-align: right;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.correlation-meter {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #eef2f7;
}

.correlation-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.corr-positive { background: var(--red); }
.corr-negative { background: var(--green); }

/* ==================== EMPTY STATE ==================== */

.empty-state {
  margin: 8px 0 0;
  padding: 12px;
  border: 1px dashed var(--line);
  border-radius: 6px;
  color: var(--muted);
  background: var(--surface-1);
  font-size: 14px;
}

/* ==================== DL ==================== */

dl {
  display: grid;
  gap: 10px;
  margin: 0;
}

dl div {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: 10px;
}

dt {
  color: var(--muted);
  font-size: 14px;
}

dd {
  margin: 0;
  word-break: break-word;
  font-size: 14px;
}

/* ==================== TABLES ==================== */

.table-wrap {
  overflow-x: auto;
  overflow-y: hidden;
  width: 100%;
  max-width: 100%;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

td {
  padding: 9px 10px;
  border-bottom: 1px solid var(--line-light);
  text-align: left;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

th {
  padding: 9px 10px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  white-space: nowrap;
  position: sticky;
  top: 0;
  z-index: 1;
  color: var(--muted);
  font-weight: 600;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  background: var(--panel);
}

tbody tr:nth-child(even) {
  background: #f8fafc;
}

tbody tr:hover {
  background: #f1f5f9;
}

/* ==================== SEMANTIC COLORS ==================== */

.red { color: var(--red); }
.green { color: var(--green); }

/* ==================== RESPONSIVE ==================== */

@media (max-width: 1180px) and (min-width: 801px) {
  .metric-strip.metrics-7 {
    grid-template-columns: repeat(12, minmax(0, 1fr));
  }

  .metric-strip.metrics-7 .metric-cell {
    grid-column: span 3;
  }

  .metric-strip.metrics-7 .metric-cell:nth-last-child(-n + 3) {
    grid-column: span 4;
  }
}

@media (max-width: 800px) {
  .dashboard-shell {
    width: min(100vw - 24px, 720px);
    padding-top: 12px;
  }

  .hero-panel {
    margin-bottom: 12px;
    padding: 12px;
  }

  .top-bar {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .price-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .price-header .quote-area {
    text-align: left;
    justify-content: flex-start;
    align-items: center;
    max-width: 100%;
  }

  .price-header .quote-area .price {
    font-size: 28px;
  }

  .price-header .quote-area .price.is-missing {
    font-size: 20px;
  }

  .price-header .quote-area .change {
    font-size: 14px;
  }

  .price-header .id-area .name {
    font-size: 28px;
    line-height: 1.05;
  }

  .metric-strip,
  .metric-strip.metrics-7 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .metric-strip.metrics-7 .metric-cell {
    grid-column: auto;
  }

  .metric-strip.metrics-7 .metric-cell:last-child {
    grid-column: 1 / -1;
  }

  .metric-strip.metrics-4,
  .metric-strip.four-col {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .meta-row {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
  }

  .meta-row .meta-item {
    min-height: 56px;
    padding: 8px;
    gap: 4px;
    font-size: 12px;
  }

  .meta-row .meta-item .meta-value {
    font-size: 14px;
  }

  .insight-strip {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .insight-strip article {
    min-height: auto;
    padding: 10px;
  }

  .insight-strip article:nth-child(n + 2) {
    display: none;
  }

  .chart-zone,
  .backtest-grid {
    grid-template-columns: 1fr;
  }

  .chart-zone > *,
  .backtest-grid > * {
    min-width: 0;
  }

  .content-grid,
  .content-grid.wide,
  .financial-snapshot-grid {
    grid-template-columns: 1fr;
  }

  .content-grid > *,
  .content-grid.wide > *,
  .financial-snapshot-grid > * {
    min-width: 0;
  }

  .trend-chart {
    height: 260px;
  }

  .panel-heading {
    flex-direction: column;
    gap: 8px;
  }
}

@media (max-width: 520px) {
  .metric-strip,
  .metric-strip.metrics-7 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .metric-strip.metrics-4,
  .metric-strip.four-col {
    grid-template-columns: 1fr;
  }

  .mini-metric-grid {
    grid-template-columns: 1fr;
  }

  .quality-facts {
    grid-template-columns: 1fr;
  }

  .mini-metric-grid > * {
    min-width: 0;
  }

  .chart-panel,
  .data-panel {
    padding: 12px;
  }

  .price-header .quote-area .price {
    font-size: 24px;
  }

  .financial-bars {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .correlation-row {
    grid-template-columns: minmax(0, 1fr) 56px;
    overflow-x: auto;
  }

  .table-wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }
}


/* ==================== FINANCIAL WORKBENCH CANVAS ==================== */

.dashboard-shell[data-visual-language="financial-workbench"] {
  width: min(1440px, 100vw);
  margin: 0 auto;
  padding: 0 28px 48px;
