/** @type {import('next').NextConfig} */
const path = require('path');

const projectRoot = __dirname;
const workspaceRoot = process.env.ALPHADECK_WORKSPACE_ROOT
  ? path.resolve(process.env.ALPHADECK_WORKSPACE_ROOT)
  : path.resolve(projectRoot, '../../..');

const nextConfig = {
  allowedDevOrigins: ['localhost', '127.0.0.1'],
  typedRoutes: true,
  // Transport configuration only; the Python bridge owns requests and access rules.
  async rewrites() {
    const port = Number(process.env.ALPHADECK_SANDBOX_MARKET_PORT || '8000');
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('Invalid Python market bridge port');
    return [{ source: '/api/market/:path*', destination: 'http://127.0.0.1:' + port + '/api/v1/:path*' }];
  },
  // Next 16 requires the tracing and Turbopack roots to match. Keeping both at
  // the generated project boundary prevents discovery of platform entrypoints
  // such as src/proxy.ts while the node_modules symlink remains resolvable.
  outputFileTracingRoot: projectRoot,
  turbopack: {
    root: projectRoot,
  },
};

module.exports = nextConfig;

